head.script:
scwin.onpageload = function() {
	requires("uiplugin.popup");
	textarea2.setValue("자식팝업창에 전달할 파라메터 데이터11");
};
scwin.trigger1_onclick = function(e) {
	var option = {
		id: 'popup_' + Math.floor(Math.random() * 10),
		type: 'window',
		width: '550px',
		height: '300px',
		top: pageYOffset,
		left: 300,
		popupName: 'popupName',
		modal: true,
		useIFrame: "true",
		style: "",
		resizable: true,
		status: false,
		menubar: false,
		scrollbars: true,
		title: false,
		xml: textarea2.getValue(),
		srcData: "sendData",
		destData: "receiveData",
		closeAction: "doClose"
	};
	WebSquare.util.openPopup("", option);
};
scwin.__checkErrLog = function() {
	return WebSquare.logger.getErrorLog();
}
